//! Feasibility prototype: iceoryx2 pub/sub inside one process.
//! - 1t: same thread publishes then receives (loopback)
//! - 2t: main -> worker -> main round-trip over two services

use std::hint::black_box;
use std::thread;
use std::time::Instant;

use iceoryx2::prelude::*;

const N: u64 = 200_000;

fn one_thread() -> Result<(), Box<dyn std::error::Error>> {
    let node = NodeBuilder::new().create::<ipc::Service>()?;
    let service = node
        .service_builder(&"ice-proto-1t".try_into()?)
        .publish_subscribe::<u64>()
        .open_or_create()?;
    let publisher = service.publisher_builder().create()?;
    let subscriber = service.subscriber_builder().create()?;

    // warmup
    for i in 0..1000u64 {
        publisher.send_copy(i)?;
        while subscriber.receive()?.is_none() {}
    }

    let start = Instant::now();
    for i in 0..N {
        publisher.send_copy(i)?;
        loop {
            if let Some(sample) = subscriber.receive()? {
                black_box(*sample);
                break;
            }
        }
    }
    let el = start.elapsed();
    println!(
        "1t loopback: {} iters, {:.1} ns/iter",
        N,
        el.as_nanos() as f64 / N as f64
    );
    Ok(())
}

fn two_threads() -> Result<(), Box<dyn std::error::Error>> {
    let node = NodeBuilder::new().create::<ipc::Service>()?;
    let req = node
        .service_builder(&"ice-proto-2t-req".try_into()?)
        .publish_subscribe::<u64>()
        .open_or_create()?;
    let resp = node
        .service_builder(&"ice-proto-2t-resp".try_into()?)
        .publish_subscribe::<u64>()
        .open_or_create()?;

    let req_tx = req.publisher_builder().create()?;
    let resp_rx = resp.subscriber_builder().create()?;

    let worker = thread::spawn(move || -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        // worker gets its own node in the same process
        let node = NodeBuilder::new().create::<ipc::Service>()?;
        let req = node
            .service_builder(&"ice-proto-2t-req".try_into()?)
            .publish_subscribe::<u64>()
            .open_or_create()?;
        let resp = node
            .service_builder(&"ice-proto-2t-resp".try_into()?)
            .publish_subscribe::<u64>()
            .open_or_create()?;
        let req_rx = req.subscriber_builder().create()?;
        let resp_tx = resp.publisher_builder().create()?;
        let mut echoed = 0u64;
        while echoed < N + 1000 {
            if let Some(sample) = req_rx.receive()? {
                resp_tx.send_copy(*sample)?;
                echoed += 1;
            } else {
                core::hint::spin_loop();
            }
        }
        Ok(())
    });

    // warmup
    for i in 0..1000u64 {
        req_tx.send_copy(i)?;
        loop {
            if let Some(s) = resp_rx.receive()? {
                black_box(*s);
                break;
            }
            core::hint::spin_loop();
        }
    }

    let start = Instant::now();
    for i in 0..N {
        req_tx.send_copy(i)?;
        loop {
            if let Some(s) = resp_rx.receive()? {
                black_box(*s);
                break;
            }
            core::hint::spin_loop();
        }
    }
    let el = start.elapsed();
    println!(
        "2t round-trip: {} iters, {:.1} ns/iter",
        N,
        el.as_nanos() as f64 / N as f64
    );

    worker.join().unwrap().map_err(|e| e.to_string())?;
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    one_thread()?;
    two_threads()?;
    Ok(())
}

