pub fn run(cfg: &RunCfg) {
    let mut bench = IcePubSub1Thread::new();
    let (hist, outer, inner, duration_s) = harness::run_adaptive(&mut bench, cfg);
    harness::print_report(bench.name(), outer, inner, duration_s, &hist, cfg.overhead);
