18	/// Main → worker → main round-trip over two iceoryx2
19	/// publish/subscribe services (one per direction — pub/sub has no
20	/// return path, so the echo needs a second service). Both ends
21	/// spin-receive (`Subscriber::receive` is non-blocking only), so
22	/// this measures the spin-spin fast path, comparable to a hot
23	/// `mpsc-2t`, not park/wake cost.
24	///
25	/// See `ice-ps-1t` for the service-name / `/dev/shm` residue notes.
26	pub struct IcePubSub2Thread {
27	    req_tx: Publisher<ipc::Service, u64, ()>,
28	    resp_rx: Subscriber<ipc::Service, u64, ()>,
29	    // Declared after the ports: fields drop in declaration order,
30	    // and dropping the node while ports live trips iceoryx2's
31	    // dead-node detection (a noisy [W] on the next node creation).
32	    _node: Node<ipc::Service>,
33	    stop: Arc<AtomicBool>,
34	    worker: Option<thread::JoinHandle<()>>,
35	    counter: u64,
36	}
