38	/// Build the two service names (req, resp) shared by both threads.
39	fn service_names() -> (String, String) {
40	    let pid = std::process::id();
41	    (
42	        format!("iiac-perf-ice-ps-2t-req-{pid}"),
43	        format!("iiac-perf-ice-ps-2t-resp-{pid}"),
44	    )
45	}
