47	/// Open a pub/sub `u64` service by name on `node`.
48	fn open_service(
49	    node: &Node<ipc::Service>,
50	    name: &str,
51	) -> iceoryx2::service::port_factory::publish_subscribe::PortFactory<ipc::Service, u64, ()> {
52	    node.service_builder(&name.try_into().expect("service name"))
53	        .publish_subscribe::<u64>()
54	        .open_or_create()
55	        .expect("iceoryx2 service")
56	}
