58	impl IcePubSub2Thread {
59	    /// Spawn the echo worker, optionally pinning it to `worker_cpu`.
60	    pub fn new(worker_cpu: Option<usize>) -> Self {
61	        let (req_name, resp_name) = service_names();
62	        // Explicit default config: skips the global config-file
63	        // lookup (and its "No config file was loaded" warning) and
64	        // keeps the bench hermetic — results can't be skewed by a
65	        // machine-local iceoryx2.toml.
66	        let node = NodeBuilder::new()
67	            .config(&iceoryx2::config::Config::default())
68	            .create::<ipc::Service>()
69	            .expect("iceoryx2 node");
70	        let req_tx = open_service(&node, &req_name)
71	            .publisher_builder()
72	            .create()
73	            .expect("req publisher");
74	        let resp_rx = open_service(&node, &resp_name)
75	            .subscriber_builder()
76	            .create()
77	            .expect("resp subscriber");
78	
79	        let stop = Arc::new(AtomicBool::new(false));
80	        let worker_stop = Arc::clone(&stop);
81	        let worker = thread::spawn(move || {
82	            pin::pin_current(worker_cpu);
83	            // The worker opens the same services through its own node,
84	            // as a second process would.
85	            let node = NodeBuilder::new()
86	                .config(&iceoryx2::config::Config::default())
87	                .create::<ipc::Service>()
88	                .expect("iceoryx2 worker node");
89	            let req_rx = open_service(&node, &req_name)
90	                .subscriber_builder()
91	                .create()
92	                .expect("req subscriber");
93	            let resp_tx = open_service(&node, &resp_name)
94	                .publisher_builder()
95	                .create()
96	                .expect("resp publisher");
97	            while !worker_stop.load(Ordering::Relaxed) {
98	                if let Some(sample) = req_rx.receive().expect("worker receive") {
99	                    resp_tx.send_copy(*sample).expect("worker send_copy");
100	                } else {
101	                    core::hint::spin_loop();
102	                }
103	            }
104	        });
105	
106	        // Handshake: pub/sub has no history here, so a sample
107	        // published before the worker's subscriber connects is
108	        // silently dropped — and a lost first request would leave
109	        // step() spinning forever. Re-ping until an echo arrives,
110	        // then drain the extra echoes from repeated pings.
111	        loop {
112	            req_tx.send_copy(0).expect("handshake send");
113	            thread::sleep(std::time::Duration::from_millis(1));
114	            if resp_rx.receive().expect("handshake receive").is_some() {
115	                break;
116	            }
117	        }
118	        thread::sleep(std::time::Duration::from_millis(10));
119	        while resp_rx.receive().expect("handshake drain").is_some() {}
120	
121	        Self {
122	            req_tx,
123	            resp_rx,
124	            _node: node,
125	            stop,
126	            worker: Some(worker),
127	            counter: 0,
128	        }
129	    }
130	}
