132	impl Bench for IcePubSub2Thread {
133	    fn name(&self) -> &str {
134	        "ice-ps-2t: iceoryx2 pub/sub round-trip (2 threads)"
135	    }
136	
137	    fn step(&mut self) -> u64 {
138	        self.counter = self.counter.wrapping_add(1);
139	        self.req_tx.send_copy(self.counter).expect("send_copy");
140	        loop {
141	            if let Some(sample) = self.resp_rx.receive().expect("receive") {
142	                return black_box(*sample);
143	            }
144	            core::hint::spin_loop();
145	        }
146	    }
147	}
