149	impl Drop for IcePubSub2Thread {
150	    fn drop(&mut self) {
151	        self.stop.store(true, Ordering::Relaxed);
152	        if let Some(worker) = self.worker.take() {
153	            let _ = worker.join();
154	        }
155	    }
156	}
