17	/// Main (client) → worker (server) → main round-trip over one
18	/// iceoryx2 request/response service — the pattern's structural
19	/// advantage over pub/sub (`ice-ps-2t`), which needs a service
20	/// per direction. Both ends spin (`receive` is non-blocking
21	/// only), so this measures the spin-spin fast path, not
22	/// park/wake cost.
23	///
24	/// See `ice-ps-1t` for the service-name / `/dev/shm` residue notes.
25	pub struct IceReqRes2Thread {
26	    client: Client<ipc::Service, u64, (), u64, ()>,
27	    // Declared after the port: fields drop in declaration order,
28	    // and dropping the node while ports live trips iceoryx2's
29	    // dead-node detection (a noisy [W] on the next node creation).
30	    _node: Node<ipc::Service>,
31	    stop: Arc<AtomicBool>,
32	    worker: Option<thread::JoinHandle<()>>,
33	    counter: u64,
34	}
