36	impl IceReqRes2Thread {
37	    /// Spawn the echo-server worker, optionally pinning it to
38	    /// `worker_cpu`.
39	    pub fn new(worker_cpu: Option<usize>) -> Self {
40	        let name = format!("iiac-perf-ice-rr-2t-{}", std::process::id());
41	        // Explicit default config: skips the global config-file
42	        // lookup (and its "No config file was loaded" warning) and
43	        // keeps the bench hermetic — results can't be skewed by a
44	        // machine-local iceoryx2.toml.
45	        let node = NodeBuilder::new()
46	            .config(&iceoryx2::config::Config::default())
47	            .create::<ipc::Service>()
48	            .expect("iceoryx2 node");
49	        let client = node
50	            .service_builder(&name.as_str().try_into().expect("service name"))
51	            .request_response::<u64, u64>()
52	            .open_or_create()
53	            .expect("iceoryx2 service")
54	            .client_builder()
55	            .create()
56	            .expect("client");
57	
58	        let stop = Arc::new(AtomicBool::new(false));
59	        let worker_stop = Arc::clone(&stop);
60	        let worker_name = name.clone();
61	        let worker = thread::spawn(move || {
62	            pin::pin_current(worker_cpu);
63	            // The worker opens the same service through its own node,
64	            // as a second process would.
65	            let node = NodeBuilder::new()
66	                .config(&iceoryx2::config::Config::default())
67	                .create::<ipc::Service>()
68	                .expect("iceoryx2 worker node");
69	            let server = node
70	                .service_builder(&worker_name.as_str().try_into().expect("service name"))
71	                .request_response::<u64, u64>()
72	                .open_or_create()
73	                .expect("iceoryx2 worker service")
74	                .server_builder()
75	                .create()
76	                .expect("server");
77	            while !worker_stop.load(Ordering::Relaxed) {
78	                if let Some(request) = server.receive().expect("worker receive") {
79	                    request.send_copy(*request).expect("worker respond");
80	                } else {
81	                    core::hint::spin_loop();
82	                }
83	            }
84	        });
85	
86	        // Handshake: a request sent before the worker's server
87	        // connects is dropped, and its PendingResponse would never
88	        // resolve — a lost first request would leave step()
89	        // spinning forever. Re-request until an echo arrives; each
90	        // retry's PendingResponse is dropped and closed with it.
91	        loop {
92	            let pending = client.send_copy(0).expect("handshake send");
93	            thread::sleep(std::time::Duration::from_millis(1));
94	            if pending.receive().expect("handshake receive").is_some() {
95	                break;
96	            }
97	        }
98	
99	        Self {
100	            client,
101	            _node: node,
102	            stop,
103	            worker: Some(worker),
104	            counter: 0,
105	        }
106	    }
107	}
